    internal readonly record struct Topic(string Title, string Text, string Html);
    internal static readonly Topic[] Topics =
    [
        new("Start here", "Welcome to Haven: a custom UO world built for solo play, companions and a growing player community. You do not need to learn every command at once.\n\n## Your first session\n1. Type [bank to reach New Haven's recovery services. Explore the nearby supply stones and repair bench.\n2. Type [StarterKit to claim an eligible free starter bundle. [Cape and [Sash provide their eligible starter pieces.\n3. Keep the Adventurer's Wallet in your backpack. Type [wallet to inspect it.\n4. Type [c to claim or open your permanent companion. Pick a role, then use Guard when you want combat support.\n5. Try Haven quests and easy island combat before a mini champion spawn. Check [HavenRewards if you already outgrew training quests.\n6. Use [mystats to inspect your build and [market to browse actual merchant stock.\n\n## Keep this guide handy\nType [guide at any time, including while dead. Search for a command or topic. The Free book button puts a reusable copy in your backpack if you do not already have one in your pack or bank. Reading this guide never spends currency or activates the commands it describes.", "<basefont color=#181818>Welcome to Haven: a custom UO world built for solo play, companions and a growing player community. You do not need to learn every command at once.<br><br><b>Your first session</b><br>1. Type [bank to reach New Haven&#x27;s recovery services. Explore the nearby supply stones and repair bench.<br>2. Type [StarterKit to claim an eligible free starter bundle. [Cape and [Sash provide their eligible starter pieces.<br>3. Keep the Adventurer&#x27;s Wallet in your backpack. Type [wallet to inspect it.<br>4. Type [c to claim or open your permanent companion. Pick a role, then use Guard when you want combat support.<br>5. Try Haven quests and easy island combat before a mini champion spawn. Check [HavenRewards if you already outgrew training quests.<br>6. Use [mystats to inspect your build and [market to browse actual merchant stock.<br><br><b>Keep this guide handy</b><br>Type [guide at any time, including while dead. Search for a command or topic. The Free book button puts a reusable copy in your backpack if you do not already have one in your pack or bank. Reading this guide never spends currency or activates the commands it describes.</basefont>"),
        new("Quick commands", "Type commands in ordinary game speech, starting with [. Do not add a closing bracket. Capitalization does not matter.\n\n## Everyday essentials\n[guide - this field guide; [havenhelp is an alias.\n[bank or [ohshit - New Haven bank recovery landing.\n[c or [companion - claim/open your companion.\n[mystats - player stats and bonuses.\n[skillbudget - counted and free skills.\n[wallet - wallet balances and controls.\n[withdraw 1000 - withdraw physical gold.\n[tithe 1000 - convert wallet gold to Chivalry tithing points.\n[minax 10 - withdraw earned Minax credits as a tradeable note.\n[market - search and buy listed merchant goods.\n\n## Claims and companions\n[StarterKit, [Cape, [Sash - eligible starter claims.\n[HavenRewards - eligible outgrown Haven quest rewards.\n[HavenLuck - current luck and island bonus.\n[CompanionReport - mission history and receipts.\n[CompanionAuto - idle/AFK mission controls.\n[CompanionAuto off - disable idle and manual AFK mode.\n[CompanionGrind - inspect an existing offline assignment.\n[CompanionGrind off - stop that assignment; this is not a start command.\n\n## Pets and exploration\n[PetTrain - target an owned pet for training.\n[PetMenu - target your pet or its health bar for its menu.\n[PetPack - access a supported custom pet pack.\n[PetFollow, [PetGuard, [PetStay, [PetStop, [PetCome - normal pet orders.\n[PetAttack - issue attack and select a target.\n[home - your assigned private island, if available.\n[frontiers, [shadowguard, [blackthorn, [chelonia, [abyss - installed frontier content.\n[voyage, [tide - supported sea controls.\n[expeditions - regional expedition controls.\n[encounters - wandering encounter controls and records.\n[guildcrew - guild worker controls.\n[puzzle - nearby supported companion puzzle assistance.\n[WorldStatus - world population status.", "<basefont color=#181818>Type commands in ordinary game speech, starting with [. Do not add a closing bracket. Capitalization does not matter.<br><br><b>Everyday essentials</b><br>[guide - this field guide; [havenhelp is an alias.<br>[bank or [ohshit - New Haven bank recovery landing.<br>[c or [companion - claim/open your companion.<br>[mystats - player stats and bonuses.<br>[skillbudget - counted and free skills.<br>[wallet - wallet balances and controls.<br>[withdraw 1000 - withdraw physical gold.<br>[tithe 1000 - convert wallet gold to Chivalry tithing points.<br>[minax 10 - withdraw earned Minax credits as a tradeable note.<br>[market - search and buy listed merchant goods.<br><br><b>Claims and companions</b><br>[StarterKit, [Cape, [Sash - eligible starter claims.<br>[HavenRewards - eligible outgrown Haven quest rewards.<br>[HavenLuck - current luck and island bonus.<br>[CompanionReport - mission history and receipts.<br>[CompanionAuto - idle/AFK mission controls.<br>[CompanionAuto off - disable idle and manual AFK mode.<br>[CompanionGrind - inspect an existing offline assignment.<br>[CompanionGrind off - stop that assignment; this is not a start command.<br><br><b>Pets and exploration</b><br>[PetTrain - target an owned pet for training.<br>[PetMenu - target your pet or its health bar for its menu.<br>[PetPack - access a supported custom pet pack.<br>[PetFollow, [PetGuard, [PetStay, [PetStop, [PetCome - normal pet orders.<br>[PetAttack - issue attack and select a target.<br>[home - your assigned private island, if available.<br>[frontiers, [shadowguard, [blackthorn, [chelonia, [abyss - installed frontier content.<br>[voyage, [tide - supported sea controls.<br>[expeditions - regional expedition controls.<br>[encounters - wandering encounter controls and records.<br>[guildcrew - guild worker controls.<br>[puzzle - nearby supported companion puzzle assistance.<br>[WorldStatus - world population status.</basefont>"),
        new("Wallet & shops", "## Three currencies\nThe Adventurer's Wallet supports gold, Haven marks and Astral shards. Keep it in your backpack. Double-click it to collect eligible nearby currency; use [wallet for its menu. Some rewards arrive directly in your pack first, so inspect both your pack and wallet.\n\n## Paying and withdrawing\nSupported supply stones, market purchases, ordinary merchants, stables and gear upgrades can use wallet gold. If an activity requires physical coins, type [withdraw 1000 or say withdraw 1000. Withdrawal still needs room in your backpack.\n\n## Chivalry\n[tithe 1000 exchanges 1,000 wallet gold for 1,000 tithing points, up to the 100,000-point limit. It is an actual payment, not a free refill.\n\n## Inspect before buying\nSelect a stone item to open its full preview. Hover tooltips are convenient, but the preview is the place to check bonuses, price and requirements. Starter claims are free when eligible; replacement supplies and special rewards have their displayed prices.\n\n## Repairs\nThe repair bench near the services offers Repair all for supported equipped/carried gear, with a small gold charge and no normal repair durability loss. Restoration is a separate option for maximum durability. Check the displayed price before confirming.", "<basefont color=#181818><b>Three currencies</b><br>The Adventurer&#x27;s Wallet supports gold, Haven marks and Astral shards. Keep it in your backpack. Double-click it to collect eligible nearby currency; use [wallet for its menu. Some rewards arrive directly in your pack first, so inspect both your pack and wallet.<br><br><b>Paying and withdrawing</b><br>Supported supply stones, market purchases, ordinary merchants, stables and gear upgrades can use wallet gold. If an activity requires physical coins, type [withdraw 1000 or say withdraw 1000. Withdrawal still needs room in your backpack.<br><br><b>Chivalry</b><br>[tithe 1000 exchanges 1,000 wallet gold for 1,000 tithing points, up to the 100,000-point limit. It is an actual payment, not a free refill.<br><br><b>Inspect before buying</b><br>Select a stone item to open its full preview. Hover tooltips are convenient, but the preview is the place to check bonuses, price and requirements. Starter claims are free when eligible; replacement supplies and special rewards have their displayed prices.<br><br><b>Repairs</b><br>The repair bench near the services offers Repair all for supported equipped/carried gear, with a small gold charge and no normal repair durability loss. Restoration is a separate option for maximum durability. Check the displayed price before confirming.</basefont>"),
        new("Your companion", "## Claim and communicate\n[c opens your permanent companion and claims one if you do not have one. Orders, Stats, Role and Tasks divide the controls into smaller screens. The shared Pack lets you supply better equipment and carry loot, including bags inside it.\n\n## Choose a role\nUse melee, archer, healer, bard or caster roles to suit the fight. Guard supports combat around you; Stay or a noncombat order can explain why a companion is not attacking. Switching roles changes equipment needs. Companion gear evolves across roles; you can also offer better gear.\n\n## Healing and support\nCapable companions automatically heal and cure, and can help resurrect. Bandage support is supplied by the companion system. Bard support develops with skills and uses paired mastery effects when eligible, including support for eligible party pets. Caster/Spellweaver behavior chooses spells according to the situation; an area spell is not useful in every fight.\n\n## If something looks wrong\nCheck HP, mana, stamina, role and current order in Stats/Orders. Use Refresh for a stuck companion and Heal / rez for recovery. Check Tasks before recalling: it may be away on a mission. Refresh is a recovery control, not a way to duplicate mission rewards.", "<basefont color=#181818><b>Claim and communicate</b><br>[c opens your permanent companion and claims one if you do not have one. Orders, Stats, Role and Tasks divide the controls into smaller screens. The shared Pack lets you supply better equipment and carry loot, including bags inside it.<br><br><b>Choose a role</b><br>Use melee, archer, healer, bard or caster roles to suit the fight. Guard supports combat around you; Stay or a noncombat order can explain why a companion is not attacking. Switching roles changes equipment needs. Companion gear evolves across roles; you can also offer better gear.<br><br><b>Healing and support</b><br>Capable companions automatically heal and cure, and can help resurrect. Bandage support is supplied by the companion system. Bard support develops with skills and uses paired mastery effects when eligible, including support for eligible party pets. Caster/Spellweaver behavior chooses spells according to the situation; an area spell is not useful in every fight.<br><br><b>If something looks wrong</b><br>Check HP, mana, stamina, role and current order in Stats/Orders. Use Refresh for a stuck companion and Heal / rez for recovery. Check Tasks before recalling: it may be away on a mission. Refresh is a recovery control, not a way to duplicate mission rewards.</basefont>"),
        new("Missions & AFK", "## Send a mission\nOpen [c, then Tasks. Pick combat, resources or a taming mission and inspect its requirements. The menu shows relevant skills. Choose an available duration; longer trips take longer and use the displayed reward rules. Early return is different from successful completion.\n\n## Taming trips\nChoose a pet family from the list. Taming and Animal Lore gate eligibility. Custom pet rarity and success are rolls, so an eligible mission does not guarantee a rare pet. Successful tickets can be inspected with Animal Lore before claiming. Some trips also bring useful taming supplies.\n\n## AFK and offline are different\n[CompanionAuto opens idle and manual AFK controls. Manual AFK remains active even if you move or perform another action; turn it off explicitly. Select the desired focus and duration there. An existing offline gear assignment runs until your next login and preserves its schedule through restarts. [CompanionGrind reports it; [CompanionGrind off stops it.\n\n## Returning loot\nRewards go directly into the shared pack, supported resource deeds or its Resource Ledger. There is no extra reward bag for each run. Leave free capacity: a full pack can stop work. [CompanionReport shows recorded runs, training, gear progress and loot receipts. The return report separates recorded results from older untracked loot.", "<basefont color=#181818><b>Send a mission</b><br>Open [c, then Tasks. Pick combat, resources or a taming mission and inspect its requirements. The menu shows relevant skills. Choose an available duration; longer trips take longer and use the displayed reward rules. Early return is different from successful completion.<br><br><b>Taming trips</b><br>Choose a pet family from the list. Taming and Animal Lore gate eligibility. Custom pet rarity and success are rolls, so an eligible mission does not guarantee a rare pet. Successful tickets can be inspected with Animal Lore before claiming. Some trips also bring useful taming supplies.<br><br><b>AFK and offline are different</b><br>[CompanionAuto opens idle and manual AFK controls. Manual AFK remains active even if you move or perform another action; turn it off explicitly. Select the desired focus and duration there. An existing offline gear assignment runs until your next login and preserves its schedule through restarts. [CompanionGrind reports it; [CompanionGrind off stops it.<br><br><b>Returning loot</b><br>Rewards go directly into the shared pack, supported resource deeds or its Resource Ledger. There is no extra reward bag for each run. Leave free capacity: a full pack can stop work. [CompanionReport shows recorded runs, training, gear progress and loot receipts. The return report separates recorded results from older untracked loot.</basefont>"),
        new("Books & storage", "## Resource Ledger\nAbsorb supported commodity deeds into a ledger. Its balances can be combined and withdrawn as a new deed in your chosen quantity. A ledger in the companion pack receives supported mission resources automatically. Use Transfer all on that ledger and target your own ledger to transfer its balances. Both books and ownership must be valid.\n\n## Champion's Codex\nStore supported power scrolls and related progression items by skill and tier. Choose individual combine recipes to make higher scrolls, or a supported reverse recipe to split one down. Unselected skill/tier stock remains available. Inspect the recipe before spending scrolls.\n\n## Backpack slots and weight\nThe ledger and codex each count as one backpack item regardless of stored entries. Extracted deeds and scrolls become ordinary inventory items again and require space. This does not make every item or container weightless.\n\n## Resource carrying bags\nResource satchels reduce weight for their supported resources. Ordinary armor or unrelated items do not receive that reduction. Keep the ledger for bulk stored materials and the satchel for materials you actively carry.", "<basefont color=#181818><b>Resource Ledger</b><br>Absorb supported commodity deeds into a ledger. Its balances can be combined and withdrawn as a new deed in your chosen quantity. A ledger in the companion pack receives supported mission resources automatically. Use Transfer all on that ledger and target your own ledger to transfer its balances. Both books and ownership must be valid.<br><br><b>Champion&#x27;s Codex</b><br>Store supported power scrolls and related progression items by skill and tier. Choose individual combine recipes to make higher scrolls, or a supported reverse recipe to split one down. Unselected skill/tier stock remains available. Inspect the recipe before spending scrolls.<br><br><b>Backpack slots and weight</b><br>The ledger and codex each count as one backpack item regardless of stored entries. Extracted deeds and scrolls become ordinary inventory items again and require space. This does not make every item or container weightless.<br><br><b>Resource carrying bags</b><br>Resource satchels reduce weight for their supported resources. Ordinary armor or unrelated items do not receive that reduction. Keep the ledger for bulk stored materials and the satchel for materials you actively carry.</basefont>"),
        new("Pets & training", "## Inspect first\nAnimal Lore shows pet stats, skills, caps, training and abilities. It also works on supported pet tickets and shrunken animals. A ticket's preview lets you decide before opening it. Ticket pets are ready to bond when fed appropriate food.\n\n## Train and spend\nUse Animal Training from lore or [PetTrain. Begin Training, earn progress through eligible activity, then spend the available training budget. Stat, resistance, skill-cap and ability choices have their own requirements. Skill cap tiers correspond to 105/110/115/120 power scrolls and require the matching scroll. Training does not bypass individual limits or follower requirements.\n\n## Custom species and rarity\nCustom pets can have distinct attacks, regeneration, defenses, themed ground damage, packs or sea utility. Rarity changes more than a title, including appearance and eligible innate bonuses. Legendary custom pets start at one control slot and can roll over-cap skills. These rules do not turn ordinary animal species into Legendary custom pets.\n\n## Handling\nSupply stones offer supported bonding/shrinking tools and house posts. Use pet resurrection services near banks/stables. A pet pack belongs to that pet and its owner. For hotkeys, bind a client macro to [PetFollow, [PetGuard or [PetAttack; normal ownership, range and obedience still apply.", "<basefont color=#181818><b>Inspect first</b><br>Animal Lore shows pet stats, skills, caps, training and abilities. It also works on supported pet tickets and shrunken animals. A ticket&#x27;s preview lets you decide before opening it. Ticket pets are ready to bond when fed appropriate food.<br><br><b>Train and spend</b><br>Use Animal Training from lore or [PetTrain. Begin Training, earn progress through eligible activity, then spend the available training budget. Stat, resistance, skill-cap and ability choices have their own requirements. Skill cap tiers correspond to 105/110/115/120 power scrolls and require the matching scroll. Training does not bypass individual limits or follower requirements.<br><br><b>Custom species and rarity</b><br>Custom pets can have distinct attacks, regeneration, defenses, themed ground damage, packs or sea utility. Rarity changes more than a title, including appearance and eligible innate bonuses. Legendary custom pets start at one control slot and can roll over-cap skills. These rules do not turn ordinary animal species into Legendary custom pets.<br><br><b>Handling</b><br>Supply stones offer supported bonding/shrinking tools and house posts. Use pet resurrection services near banks/stables. A pet pack belongs to that pet and its owner. For hotkeys, bind a client macro to [PetFollow, [PetGuard or [PetAttack; normal ownership, range and obedience still apply.</basefont>"),
        new("Gear & builds", "## Character limits\nPlayers have a 1,000-point counted skill cap and a 300 base stat cap before applicable bonuses/scrolls. Animal Taming, Animal Lore, Focus and Snooping are free skills outside the counted total; their individual caps still apply. Use [mystats and [skillbudget to see the effective values.\n\n## What evolves\nSpecial starter items, supported Haven quest rewards, Haven jewelry, Astral purchases, compatible Legendary Artifact drops and companion equipment have custom progression. Ordinary random equipment does not all level. Inspect an item's progression tooltip or menu to see its actual rules.\n\n## Fighters and casters\nStarter choices include weapons and a grimoire, plus earrings, cape and sash. Companion equipment develops broadly because its role can change. Weapon and spellbook benefits differ; use the appropriate item for your build. Jewelry sets can add combined bonuses, and eligible high-level gear can grant an extra follower-cap benefit.\n\n## Manual upgrades versus experience\nSome items use earned experience; others also have tier upgrades or currency costs. Check the item menu instead of assuming wearing it alone performs every upgrade. Haven marks and Astral shards buy stronger goals to work toward.", "<basefont color=#181818><b>Character limits</b><br>Players have a 1,000-point counted skill cap and a 300 base stat cap before applicable bonuses/scrolls. Animal Taming, Animal Lore, Focus and Snooping are free skills outside the counted total; their individual caps still apply. Use [mystats and [skillbudget to see the effective values.<br><br><b>What evolves</b><br>Special starter items, supported Haven quest rewards, Haven jewelry, Astral purchases, compatible Legendary Artifact drops and companion equipment have custom progression. Ordinary random equipment does not all level. Inspect an item&#x27;s progression tooltip or menu to see its actual rules.<br><br><b>Fighters and casters</b><br>Starter choices include weapons and a grimoire, plus earrings, cape and sash. Companion equipment develops broadly because its role can change. Weapon and spellbook benefits differ; use the appropriate item for your build. Jewelry sets can add combined bonuses, and eligible high-level gear can grant an extra follower-cap benefit.<br><br><b>Manual upgrades versus experience</b><br>Some items use earned experience; others also have tier upgrades or currency costs. Check the item menu instead of assuming wearing it alone performs every upgrade. Haven marks and Astral shards buy stronger goals to work toward.</basefont>"),
        new("Haven rewards", "## The island advantage\nThe configured New Haven island area in Trammel grants players +1,000 Luck and accelerated skill training toward 100. The luck benefit ends when you leave its area. [HavenLuck shows whether it is currently applied.\n\n## Training quests\nComplete eligible Haven training quests for their rewards. If your skills already exceed an eligible quest's training threshold, try [HavenRewards for its catch-up reward claim. Claims are recorded; repeating a command does not mean unlimited duplicate items.\n\n## Boss and mini champion\nThe Old Haven boss and the island mini champion are separate activities. The mini champion uses themed waves and a final boss, designed as an accessible progression activity. Eligible participants receive personal completion rewards, including gold and supported scroll/currency rolls. Resource rewards are deeds. Normal wave corpses clear faster than the boss corpse.\n\n## Long-term rewards\nCollect Haven marks for special jewelry and other Haven rewards. Astral shards buy their own special items. Alacrity and Transcendence scrolls are possible mini-champ rewards, not guaranteed on every completion. Island vampiric steeds have special wild tuning; a tamed pet's rules differ.", "<basefont color=#181818><b>The island advantage</b><br>The configured New Haven island area in Trammel grants players +1,000 Luck and accelerated skill training toward 100. The luck benefit ends when you leave its area. [HavenLuck shows whether it is currently applied.<br><br><b>Training quests</b><br>Complete eligible Haven training quests for their rewards. If your skills already exceed an eligible quest&#x27;s training threshold, try [HavenRewards for its catch-up reward claim. Claims are recorded; repeating a command does not mean unlimited duplicate items.<br><br><b>Boss and mini champion</b><br>The Old Haven boss and the island mini champion are separate activities. The mini champion uses themed waves and a final boss, designed as an accessible progression activity. Eligible participants receive personal completion rewards, including gold and supported scroll/currency rolls. Resource rewards are deeds. Normal wave corpses clear faster than the boss corpse.<br><br><b>Long-term rewards</b><br>Collect Haven marks for special jewelry and other Haven rewards. Astral shards buy their own special items. Alacrity and Transcendence scrolls are possible mini-champ rewards, not guaranteed on every completion. Island vampiric steeds have special wild tuning; a tamed pet&#x27;s rules differ.</basefont>"),
        new("Masteries", "## Two different books\nThe Shard mastery manual is a custom bonus item. The regular Book of Masteries is the ability book, with supported mastery abilities and primers. Training Supplies offers these separately. Buying the custom manual is not the same as learning the regular book's abilities.\n\n## Using the regular book\nAcquire the book and appropriate primer, meet its skill requirements, learn the mastery and select it. The selected mastery and switch cooldown matter. Active abilities are used through the book; passive entries are not ordinary castable spells. Inspect the ability for its costs and conditions.\n\n## Bards\nEach bard mastery has a pair of effects. An eligible bard companion uses both for its selected mastery and supports eligible nearby party members and pets. Higher skills improve supported effects. Icons and actual bonuses should clear when range, party, role or mission state no longer qualifies.\n\n## Compatibility rules\nThis build includes a compatible mastery system. Some formulas are shard-specific: Saving Throw gives a chance to resist disarm, not immunity; Resilience reduces supported harmful durations and provides a poison-resistance chance. It does not remove every negative effect automatically.", "<basefont color=#181818><b>Two different books</b><br>The Shard mastery manual is a custom bonus item. The regular Book of Masteries is the ability book, with supported mastery abilities and primers. Training Supplies offers these separately. Buying the custom manual is not the same as learning the regular book&#x27;s abilities.<br><br><b>Using the regular book</b><br>Acquire the book and appropriate primer, meet its skill requirements, learn the mastery and select it. The selected mastery and switch cooldown matter. Active abilities are used through the book; passive entries are not ordinary castable spells. Inspect the ability for its costs and conditions.<br><br><b>Bards</b><br>Each bard mastery has a pair of effects. An eligible bard companion uses both for its selected mastery and supports eligible nearby party members and pets. Higher skills improve supported effects. Icons and actual bonuses should clear when range, party, role or mission state no longer qualifies.<br><br><b>Compatibility rules</b><br>This build includes a compatible mastery system. Some formulas are shard-specific: Saving Throw gives a chance to resist disarm, not immunity; Resilience reduces supported harmful durations and provides a poison-resistance chance. It does not remove every negative effect automatically.</basefont>"),
        new("Travel & recovery", "## Your safe return\n[bank and [ohshit use the New Haven bank recovery landing near the resurrection service. Talk to the nearby resurrection and corpse recovery NPCs as needed. A pet resurrection service is also available at the recovery area and supported stables. Travel rules still decide whether a particular action is allowed.\n\n## Moving around\nThe travel book lists town and dungeon destinations in compact pages. The bank service/gate network connects you to the Commons community center. [frontiers opens installed frontier choices. Original Shadowguard and Blackthorn entrances use their familiar map locations with this build's matching map files.\n\n## Treasure travel\nThe golden-shovel reward can use a decoded treasure map to reach a suitable dig location. It does not automatically solve every map, remove guardians or finish digging. Keep the decoded map and use normal treasure-hunting skills.\n\n## Houses and private islands\n[home takes you to your assigned island if one is configured. It is not an automatic free island claim for every account. Use the travel book or recovery commands when you need public services.", "<basefont color=#181818><b>Your safe return</b><br>[bank and [ohshit use the New Haven bank recovery landing near the resurrection service. Talk to the nearby resurrection and corpse recovery NPCs as needed. A pet resurrection service is also available at the recovery area and supported stables. Travel rules still decide whether a particular action is allowed.<br><br><b>Moving around</b><br>The travel book lists town and dungeon destinations in compact pages. The bank service/gate network connects you to the Commons community center. [frontiers opens installed frontier choices. Original Shadowguard and Blackthorn entrances use their familiar map locations with this build&#x27;s matching map files.<br><br><b>Treasure travel</b><br>The golden-shovel reward can use a decoded treasure map to reach a suitable dig location. It does not automatically solve every map, remove guardians or finish digging. Keep the decoded map and use normal treasure-hunting skills.<br><br><b>Houses and private islands</b><br>[home takes you to your assigned island if one is configured. It is not an automatic free island claim for every account. Use the travel book or recovery commands when you need public services.</basefont>"),
        new("Market & guilds", "## Browse from anywhere safe\n[market searches the Commons merchant directory. Filter by trade or type an item name. Inspect the actual item and price before buying. Supported purchases spend wallet gold and deliver to your backpack; you must be out of combat and have space.\n\n## Finite, produced stock\nArtisans perform timed gathering/crafting steps and list their results. Smiths and tailors also work on bulk orders. Gatherers sell resource deeds. Adventurers consign eligible surplus equipment. Artifact and gear-set stalls can be empty until bots supply qualifying loot. Dungeon crews fight real encounters; elapsed mission time never creates dungeon rewards. Each stall has limited listing space.\n\n## Community services\nVisit the Commons for merchants, travel/rune services and supported training utilities. A market item is a real listing, so another buyer can purchase it first.\n\n## Guild crews\n[guildcrew provides the supported recruitment, job and history controls for your guild workers. Assign gathering, crafting or training, or take workers into supported party adventures. Ownership and guild permissions matter. Some crafting recipes still lack automatic supplies; check work history when production stalls.\n\n## Pets and pet supplies\nTamer bots consign eligible wild pets they actually tame, while leaving previously owned pets and nearby players alone. Search Pets for transferable tickets. Select Inspect pet stats before buying. The ticket preserves that exact animal and its rarity. Buy with wallet gold, then claim from your pack with enough follower slots. Feed the pet to bond when you meet its normal taming requirement. Pet Supplies makes bonding potions, reusable leashes and house shrinking posts through timed gathering and crafting.\n\n## Physical dungeon crews\nThe Commons recruits available, skilled bots for Blackthorn, Shadowguard, Doom, the Stygian Abyss and pirate encounters. They travel to the entrance, fight and use supported room mechanics in the actual world. They can die or fail. There is no timed dungeon reward generator. Existing dungeon crawlers continue adventuring as well.\n\nWhen a player arrives, unassigned dungeon bots offer to join or leave. Accept within 30 seconds as party leader with enough free slots; decline or ignore to make them leave. Guild workers and bots already helping another player are protected. Shadowguard currently has reserved rooms for one group at a time, rather than unlimited private copies. Bot crews yield their reserved room when a player arrives at the entrance.\n\n## Party loot and dungeon stock\nWhile grouped with bots, their collected loot goes to the real party leader's nearby, owned companion when its pack can accept it; otherwise it goes to the player's backpack. With multiple human players, the human party leader receives the bot loot. Bots do not take unrelated corpses or player-owned pets.\n\nSolo bot crews can sell earned Minax credit notes, pirate cargo, Doom recipes and artifacts, power scrolls and compatible dungeon materials. Stock depends on real kills and completed encounters. Full stalls and failed runs can delay new listings. The market preview identifies the producer.\n\nDouble-click a purchased Minax credit note to add its exact amount to [expeditions. Type [minax 10 to withdraw ten of your earned credits as a tradeable note. Doom recipes require their matching artifact and the stated crafting materials. Pirate cargo is redeemed at the corsair dispatch board.", "<basefont color=#181818><b>Browse from anywhere safe</b><br>[market searches the Commons merchant directory. Filter by trade or type an item name. Inspect the actual item and price before buying. Supported purchases spend wallet gold and deliver to your backpack; you must be out of combat and have space.<br><br><b>Finite, produced stock</b><br>Artisans perform timed gathering/crafting steps and list their results. Smiths and tailors also work on bulk orders. Gatherers sell resource deeds. Adventurers consign eligible surplus equipment. Artifact and gear-set stalls can be empty until bots supply qualifying loot. Dungeon crews fight real encounters; elapsed mission time never creates dungeon rewards. Each stall has limited listing space.<br><br><b>Community services</b><br>Visit the Commons for merchants, travel/rune services and supported training utilities. A market item is a real listing, so another buyer can purchase it first.<br><br><b>Guild crews</b><br>[guildcrew provides the supported recruitment, job and history controls for your guild workers. Assign gathering, crafting or training, or take workers into supported party adventures. Ownership and guild permissions matter. Some crafting recipes still lack automatic supplies; check work history when production stalls.<br><br><b>Pets and pet supplies</b><br>Tamer bots consign eligible wild pets they actually tame, while leaving previously owned pets and nearby players alone. Search Pets for transferable tickets. Select Inspect pet stats before buying. The ticket preserves that exact animal and its rarity. Buy with wallet gold, then claim from your pack with enough follower slots. Feed the pet to bond when you meet its normal taming requirement. Pet Supplies makes bonding potions, reusable leashes and house shrinking posts through timed gathering and crafting.<br><br><b>Physical dungeon crews</b><br>The Commons recruits available, skilled bots for Blackthorn, Shadowguard, Doom, the Stygian Abyss and pirate encounters. They travel to the entrance, fight and use supported room mechanics in the actual world. They can die or fail. There is no timed dungeon reward generator. Existing dungeon crawlers continue adventuring as well.<br><br>When a player arrives, unassigned dungeon bots offer to join or leave. Accept within 30 seconds as party leader with enough free slots; decline or ignore to make them leave. Guild workers and bots already helping another player are protected. Shadowguard currently has reserved rooms for one group at a time, rather than unlimited private copies. Bot crews yield their reserved room when a player arrives at the entrance.<br><br><b>Party loot and dungeon stock</b><br>While grouped with bots, their collected loot goes to the real party leader&#x27;s nearby, owned companion when its pack can accept it; otherwise it goes to the player&#x27;s backpack. With multiple human players, the human party leader receives the bot loot. Bots do not take unrelated corpses or player-owned pets.<br><br>Solo bot crews can sell earned Minax credit notes, pirate cargo, Doom recipes and artifacts, power scrolls and compatible dungeon materials. Stock depends on real kills and completed encounters. Full stalls and failed runs can delay new listings. The market preview identifies the producer.<br><br>Double-click a purchased Minax credit note to add its exact amount to [expeditions. Type [minax 10 to withdraw ten of your earned credits as a tradeable note. Doom recipes require their matching artifact and the stated crafting materials. Pirate cargo is redeemed at the corsair dispatch board.</basefont>"),
        new("Dungeons", "## Doom\nThe gauntlet has room/boss controllers, artifact rewards and supported artifact progression/reforging. Use its normal route and complete the fights. Stronger encounters deserve a prepared companion and suitable gear.\n\n## Shadowguard\nUse the original Eodon entrance or the installed [shadowguard shortcut. The custom encounter sequence includes Bar, Orchard, Armory, Fountain, Belfry and Roof. Orchard has simplified help. [puzzle asks for nearby supported companion puzzle assistance; it does not solve every dungeon mechanism in the game.\n\n## Blackthorn\nThe original Trammel castle stairs lead to the installed dungeon. Its compatible invasion content includes captains, beacons, credit and rewards. [blackthorn is an installed travel shortcut.\n\n## Stygian Abyss\nThe build restores supported ingredient/essence sites, routes, custom encounters and artifice crafting. Look for the Ancient Hellhound encounter and inspect its custom pet results. Full native Imbuing and every official Stygian Abyss boss are not included.\n\n## Before reporting missing terrain\nThe server and client must use the matching Haven map data. A wrong client map can make working stairs, bridges or dungeon entrances look inaccessible.", "<basefont color=#181818><b>Doom</b><br>The gauntlet has room/boss controllers, artifact rewards and supported artifact progression/reforging. Use its normal route and complete the fights. Stronger encounters deserve a prepared companion and suitable gear.<br><br><b>Shadowguard</b><br>Use the original Eodon entrance or the installed [shadowguard shortcut. The custom encounter sequence includes Bar, Orchard, Armory, Fountain, Belfry and Roof. Orchard has simplified help. [puzzle asks for nearby supported companion puzzle assistance; it does not solve every dungeon mechanism in the game.<br><br><b>Blackthorn</b><br>The original Trammel castle stairs lead to the installed dungeon. Its compatible invasion content includes captains, beacons, credit and rewards. [blackthorn is an installed travel shortcut.<br><br><b>Stygian Abyss</b><br>The build restores supported ingredient/essence sites, routes, custom encounters and artifice crafting. Look for the Ancient Hellhound encounter and inspect its custom pet results. Full native Imbuing and every official Stygian Abyss boss are not included.<br><br><b>Before reporting missing terrain</b><br>The server and client must use the matching Haven map data. A wrong client map can make working stairs, bridges or dungeon entrances look inaccessible.</basefont>"),
        new("Islands & sea", "## Your pirate estate\nAn assigned private island offers a housing area, dock, resources and local activities. [home travels to your assigned estate. Bring the appropriate tools to gather, place a boat at suitable water and obey house/boat placement checks.\n\n## Chelonia\n[chelonia accesses the installed turtle/tortoise island content. These custom pets have their own land/sea identity and supported powers; inspect a pet with lore rather than assuming every species can do the same things.\n\n## Sea companions\nSupported tide mounts provide water travel and cargo/fishing utilities. [tide opens the relevant controls. SOS and net activities still require the appropriate items and conditions. Companion water following is supported by the custom sea systems.\n\n## Pirate voyages\n[voyage opens the supported pirate voyage content. This build includes anchored raid activities and earned cargo. A complete moving-ship and cannon-AI system remains unfinished.\n\n## Snow pets\nThe snow area has the custom bear encounter. Rarity, training and species powers should be considered together when choosing a mount or combat pet.", "<basefont color=#181818><b>Your pirate estate</b><br>An assigned private island offers a housing area, dock, resources and local activities. [home travels to your assigned estate. Bring the appropriate tools to gather, place a boat at suitable water and obey house/boat placement checks.<br><br><b>Chelonia</b><br>[chelonia accesses the installed turtle/tortoise island content. These custom pets have their own land/sea identity and supported powers; inspect a pet with lore rather than assuming every species can do the same things.<br><br><b>Sea companions</b><br>Supported tide mounts provide water travel and cargo/fishing utilities. [tide opens the relevant controls. SOS and net activities still require the appropriate items and conditions. Companion water following is supported by the custom sea systems.<br><br><b>Pirate voyages</b><br>[voyage opens the supported pirate voyage content. This build includes anchored raid activities and earned cargo. A complete moving-ship and cannon-AI system remains unfinished.<br><br><b>Snow pets</b><br>The snow area has the custom bear encounter. Rarity, training and species powers should be considered together when choosing a mount or combat pet.</basefont>"),
        new("Encounters", "## Wandering challenges\n[encounters opens the wandering encounter controls and records. These are personal progression encounters that can appear during supported play. Fight the waves and complete the event for rewards.\n\n## Difficulty and escape\nSuccessful completions advance the encounter system; failures and cancellation follow its displayed rules. Mobs are bounded to the encounter area. Leaving the boundary lets you abandon an unwanted event rather than dragging the invasion across the map.\n\n## Rewards and points\nCheck the encounter record for progress, difficulty and earned points. Rewards can include currency, useful supplies and supported special rolls. Eligible special pet outcomes are chance-based. Inspect reward choices before spending points.\n\n## Group play\nContribution and ownership determine reward eligibility. A character merely standing nearby should not receive every reward. Companions and party pets can help, but their actions still belong to the supported credit rules.", "<basefont color=#181818><b>Wandering challenges</b><br>[encounters opens the wandering encounter controls and records. These are personal progression encounters that can appear during supported play. Fight the waves and complete the event for rewards.<br><br><b>Difficulty and escape</b><br>Successful completions advance the encounter system; failures and cancellation follow its displayed rules. Mobs are bounded to the encounter area. Leaving the boundary lets you abandon an unwanted event rather than dragging the invasion across the map.<br><br><b>Rewards and points</b><br>Check the encounter record for progress, difficulty and earned points. Rewards can include currency, useful supplies and supported special rolls. Eligible special pet outcomes are chance-based. Inspect reward choices before spending points.<br><br><b>Group play</b><br>Contribution and ownership determine reward eligibility. A character merely standing nearby should not receive every reward. Companions and party pets can help, but their actions still belong to the supported credit rules.</basefont>"),
        new("Housing", "## Placement prices\nHouse placement tool prices are reduced by 90% on this build. Use the tool's displayed price before confirming. A discount does not remove ownership, collision, region or placement checks.\n\n## Where to build\nHaven-area housing and more forgiving ground checks are supported. Buildings still need a valid footprint and clear access. Terrain, static objects, roads or protected areas can rule out a spot that looks flat on the minimap.\n\n## Useful house items\nThe supply network includes supported pet shrinking posts and other utility items. Crafted furniture and stations can appear on market stalls. Read the deed or preview so you know whether an item needs house placement.\n\n## Personal island\nUse [home if an estate has been assigned to you. The current personal-island setup is not yet a full independent-island allocation system for every multiplayer account. Friends installing their own worlds should follow the build's setup guide for their own owner.", "<basefont color=#181818><b>Placement prices</b><br>House placement tool prices are reduced by 90% on this build. Use the tool&#x27;s displayed price before confirming. A discount does not remove ownership, collision, region or placement checks.<br><br><b>Where to build</b><br>Haven-area housing and more forgiving ground checks are supported. Buildings still need a valid footprint and clear access. Terrain, static objects, roads or protected areas can rule out a spot that looks flat on the minimap.<br><br><b>Useful house items</b><br>The supply network includes supported pet shrinking posts and other utility items. Crafted furniture and stations can appear on market stalls. Read the deed or preview so you know whether an item needs house placement.<br><br><b>Personal island</b><br>Use [home if an estate has been assigned to you. The current personal-island setup is not yet a full independent-island allocation system for every multiplayer account. Friends installing their own worlds should follow the build&#x27;s setup guide for their own owner.</basefont>"),
        new("Build boundaries", "## What this build is\nHaven extends a Mondain's Legacy foundation with compatible later-era and custom systems. Seeing an item, creature or destination from a later era does not imply every official expansion mechanic is present.\n\n## Still incomplete\nFull native Imbuing, all official Stygian Abyss bosses, official-complete Shadowguard/Blackthorn loot ports, moving ship/cannon AI and an independent private island for every multiplayer account remain future work. Some guild crafting recipes still need additional automatic supply support.\n\n## Friends and multiplayer\nThe current friends' build is for separate local installations first. Public/shared-server access needs its own configuration and two-player testing. Your friend's private world is separate from yours. Never distribute your Accounts/Saves directories as a fresh-install package.\n\n## Where to find more\nThe repository includes PLAYER-GUIDE.md, FRIENDS-TESTING.md and PLAYER-TEST-CHECKLIST.md. The checklist gives test IDs and expected results so reports can be reproduced. This guide describes the implemented controls; it is not a promise that every visual, balance or multiplayer edge case has been play-tested.", "<basefont color=#181818><b>What this build is</b><br>Haven extends a Mondain&#x27;s Legacy foundation with compatible later-era and custom systems. Seeing an item, creature or destination from a later era does not imply every official expansion mechanic is present.<br><br><b>Still incomplete</b><br>Full native Imbuing, all official Stygian Abyss bosses, official-complete Shadowguard/Blackthorn loot ports, moving ship/cannon AI and an independent private island for every multiplayer account remain future work. Some guild crafting recipes still need additional automatic supply support.<br><br><b>Friends and multiplayer</b><br>The current friends&#x27; build is for separate local installations first. Public/shared-server access needs its own configuration and two-player testing. Your friend&#x27;s private world is separate from yours. Never distribute your Accounts/Saves directories as a fresh-install package.<br><br><b>Where to find more</b><br>The repository includes PLAYER-GUIDE.md, FRIENDS-TESTING.md and PLAYER-TEST-CHECKLIST.md. The checklist gives test IDs and expected results so reports can be reproduced. This guide describes the implemented controls; it is not a promise that every visual, balance or multiplayer edge case has been play-tested.</basefont>"),
        new("Troubleshooting", "## Companion is idle\nCheck health, resources, Role, Orders and Tasks. Disable manual AFK if you want it back. Use Refresh for a stuck companion, and inspect [CompanionReport for completed work. Make room in its pack if missions stopped.\n\n## A purchase or withdrawal fails\nKeep the wallet in your backpack, check the correct currency, leave combat/casting where required and free inventory space. Inspect the price again: another player may have bought the last market listing.\n\n## Pet training will not apply\nCheck Begin Training progress, available points, the matching power scroll, the pet's current cap, ability limits and room for the required follower slots. Lore the pet before and after a purchase.\n\n## A starter claim is refused\nClaims have eligibility and duplicate protection. [HavenRewards is for supported outgrown quest rewards; it does not claim every quest in the game. Existing players can always read [guide even after claiming their starter bundle.\n\n## Report a useful bug\nInclude what you did, what you expected, what happened, item/pet name, time, map coordinates and a screenshot or journal message. Use the player test checklist's test ID where possible. For disappearing/duplicated items or crashes, preserve saves/logs before repeating the action.", "<basefont color=#181818><b>Companion is idle</b><br>Check health, resources, Role, Orders and Tasks. Disable manual AFK if you want it back. Use Refresh for a stuck companion, and inspect [CompanionReport for completed work. Make room in its pack if missions stopped.<br><br><b>A purchase or withdrawal fails</b><br>Keep the wallet in your backpack, check the correct currency, leave combat/casting where required and free inventory space. Inspect the price again: another player may have bought the last market listing.<br><br><b>Pet training will not apply</b><br>Check Begin Training progress, available points, the matching power scroll, the pet&#x27;s current cap, ability limits and room for the required follower slots. Lore the pet before and after a purchase.<br><br><b>A starter claim is refused</b><br>Claims have eligibility and duplicate protection. [HavenRewards is for supported outgrown quest rewards; it does not claim every quest in the game. Existing players can always read [guide even after claiming their starter bundle.<br><br><b>Report a useful bug</b><br>Include what you did, what you expected, what happened, item/pet name, time, map coordinates and a screenshot or journal message. Use the player test checklist&#x27;s test ID where possible. For disappearing/duplicated items or crashes, preserve saves/logs before repeating the action.</basefont>"),
    ];
